package com.mohymods.kingdomsmp.gametest;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.equipment.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
/** Shop/escrow acceptance with explicitly seeded canonical rank proofs. This is NOT the full24objective playthrough. */
@GameTestHolder("kingdom_smp_gear_shop_tests") @PrefixGameTestTemplate(false)
public final class FarmerGearShopRuntimeTests {
 @GameTest(template="empty",timeoutTicks=7000)
 public static void realPurchasesDeliveryAndMasterTaxes(GameTestHelper h)throws Exception{BankRuntimeTests.completeBankLoop(h,()->{try{run(h);}catch(Exception e){h.runAfterDelay(1,()->h.fail(e.toString()));}});}
 private static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();var hall=ConstructionService.lodge(server);var p=server.getPlayerList().getPlayer(hall.owner());var other=server.getPlayerList().getPlayers().stream().filter(v->v!=p).findFirst().orElseThrow();var store=CommerceService.store(server);var farm=ConstructionService.store(server).projects().stream().filter(v->v.blueprint().equals(ProfessionBlueprints.FARMER)).findFirst().orElseThrow();var farmer=level.getEntity(farm.npc());open(p,farmer);var enrolled=ProfessionService.review(p,"learn:farmer");ProfessionService.confirm(p,enrolled.nonce());boolean refused=false;try{FarmerGearService.review(p,FarmerGear.FORTUNE_X_HOE.id());}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Apprentice cannot purchase Master gear through manipulated selection");
  // Explicit fixture event/inspection proofs exercise rank validation; real event objectives have their own suites.
  for(var rank:ProfessionRank.values())for(int n=1;n<=8;n++){String id=FarmerQuests.id(rank,n);if(FarmerQuests.food(id)){
   if(id.endsWith("/j06")){var evidence=FarmerSavedData.get(server);evidence.evidence().record(p.getUUID(),rank,"cake",FarmerQuestRules.get(server).goal("j06"),null);evidence.setDirty();}
   give(p,FarmerDeliveryService.inputs(p,id));var food=FarmerDeliveryService.review(p,id);FarmerDeliveryService.confirm(p,food.nonce());if(id.endsWith("/j05"))h.assertTrue(count(p,Items.BUCKET)==32&&count(p,Items.MILK_BUCKET)==0&&count(p,Items.EGG)==0,"Real combined food delivery returns exactly32legitimate buckets through saved native exchange");
  }else if(FarmerQuests.inspection(id))store.approveFarmerInspection(UUID.randomUUID(),new UUID(0,0),p.getUUID(),id,"Explicit equipment acceptance rank fixture");else store.completeFarmerQuest(UUID.randomUUID(),p.getUUID(),id,"Explicit equipment acceptance event fixture");}
  h.assertTrue(store.professions(p.getUUID()).rank(Profession.FARMER,FarmerQuests.catalog())==ProfessionRank.MASTER,"Canonical24proof fixture satisfies approved rank bands; no raw XP promotion");store.adminSet(UUID.randomUUID(),new UUID(0,0),p.getUUID(),100000,"Equipment shop acceptance funding");var first=FarmerGearService.review(p,FarmerGear.FORTUNE_X_HOE.id());h.assertTrue(first.price()==25000,"Initial Master purchase costs configured base");FarmerGearService.confirm(p,first.nonce());refused=false;try{FarmerGearService.confirm(p,first.nonce());}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused&&store.equipmentPurchases(p.getUUID(),FarmerGear.FORTUNE_X_HOE.id())==1,"Duplicate shop confirmation creates no second delivery or purchase increment");claim(p,first.nonce());selectMaster(p);h.assertTrue(FarmerGearItems.pristine(p.getMainHandItem()),"Actual private mailbox delivers exact Fortune X component stack");
  var second=FarmerGearService.review(p,FarmerGear.FORTUNE_X_HOE.id());h.assertTrue(second.price()==37500,"Second same-item purchase compounds exactly50percent");FarmerGearService.confirm(p,second.nonce());h.assertTrue(store.balance(p.getUUID())==37500&&store.equipmentPurchases(p.getUUID(),FarmerGear.FORTUNE_X_HOE.id())==2,"Money, two native-mail entitlements and personal counter saved together");
  var bank=ConstructionService.store(server).projects().stream().filter(v->v.blueprint().equals(RoyalBankBlueprint.ID)).findFirst().orElseThrow();var banker=level.getEntity(bank.npc());open(p,banker);selectMaster(p);long removed=store.taxRemoved();var listing=AuctionService.review(p,5,"sell",1,101);AuctionService.confirm(p,listing.nonce());h.assertTrue(store.listing(listing.nonce()).orElseThrow().master(),"Real fixed listing classifies registry Master identity, not client name/NBT");store.adminSet(UUID.randomUUID(),new UUID(0,0),other.getUUID(),1000,"Master auction buyer fixture funding");open(other,banker);var buy=AuctionService.review(other,5,"buy:"+listing.nonce(),1,0);AuctionService.confirm(other,buy.nonce());h.assertTrue(store.taxRemoved()-removed==11,"Actual101coin Master sale permanently removes ceiling10percent=11coins");var sold=store.itemMailbox(other.getUUID()).stream().filter(m->!m.claimed()).filter(m->m.item().getString("id").equals(FarmerGear.FORTUNE_X_HOE.id())).findFirst().orElseThrow();claim(other,sold.id());selectMaster(other);h.assertTrue(store.professions(other.getUUID()).active().isEmpty()&&FarmerGearItems.pristine(other.getMainHandItem()),"Ordinary buyer receives and retains usable tradeable Master tool without active Farmer");
  open(p,banker);claim(p,second.nonce());selectMaster(p);var timed=AuctionService.review(p,5,"sell_timed",1,101);AuctionService.confirm(p,timed.nonce());h.assertTrue(store.listing(timed.nonce()).orElseThrow().master(),"Real timed listing preserves Master tax category");open(other,banker);var bid=AuctionService.review(other,5,"bid:"+timed.nonce(),1,101);AuctionService.confirm(other,bid.nonce());var deadline=store.listing(timed.nonce()).orElseThrow().expires();removed=store.taxRemoved();store.settleTimed(UUID.randomUUID(),new UUID(0,0),timed.nonce(),deadline,"Explicit accelerated equipment acceptance fixture");h.assertTrue(store.taxRemoved()-removed==11,"Funded timed Master settlement removes correct10percent under labeled clock acceleration");
  selectMaster(other);var order=BuyOrderService.review(other,"create",1,101);BuyOrderService.confirm(other,order.nonce());h.assertTrue(store.order(order.nonce()).orElseThrow().master(),"Actual pristine Master buy order is tagged10percent");
  open(p,farmer);store.adminSet(UUID.randomUUID(),new UUID(0,0),p.getUUID(),200000,"Third equipment purchase acceptance funding");var third=FarmerGearService.review(p,FarmerGear.FORTUNE_X_HOE.id());h.assertTrue(third.price()==56250,"Third purchase uses original base×2.25");FarmerGearService.confirm(p,third.nonce());claim(p,third.nonce());open(p,banker);selectMaster(p);removed=store.taxRemoved();var fill=BuyOrderService.review(p,"fill:"+order.nonce(),1,0);BuyOrderService.confirm(p,fill.nonce());h.assertTrue(store.taxRemoved()-removed==11&&store.order(order.nonce()).orElseThrow().remaining()==0,"Actual native Master order fill consumes tool and applies10percent exactly once");
  var reopened=EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data"));h.assertTrue(reopened.equipmentPurchases(p.getUUID(),FarmerGear.FORTUNE_X_HOE.id())==3&&reopened.taxRemoved()==store.taxRemoved(),"Gear counts, funded deliveries and all three Master tax modes reopen persistently");CommerceService.verifyReceipt(p);CommerceService.verifyReceipt(other);com.mojang.logging.LogUtils.getLogger().info("FARMER_GEAR_SHOP_ASSERTIONS_PASSED: labeled24proof rank fixture; real milk/bucket delivery, rank denial,25000/37500/56250shop purchases, mailbox components, duplicate refusal, transferable ownership and fixed/timed/order10percent tax with native escrow/reopen");h.succeed();
 }
 private static void claim(ServerPlayer p,UUID id)throws Exception{var review=AuctionService.review(p,2,id.toString(),1,0);AuctionService.confirm(p,review.nonce());}
 private static void selectMaster(ServerPlayer p){for(int slot=0;slot<36;slot++)if(FarmerGearItems.master(p.getInventory().getItem(slot))){p.getInventory().selected=slot;return;}throw new IllegalStateException("No actual Master hoe in native inventory");}
 private static int count(ServerPlayer p,Item item){int n=0;for(int i=0;i<36;i++)if(p.getInventory().getItem(i).is(item))n+=p.getInventory().getItem(i).getCount();return n;}
 private static void give(ServerPlayer p,Map<String,Integer> inputs){p.getInventory().clearContent();int slot=0;for(var entry:inputs.entrySet()){var item=BuiltInRegistries.ITEM.get(ResourceLocation.parse(entry.getKey()));int left=entry.getValue();while(left>0){int n=Math.min(left,new ItemStack(item).getMaxStackSize());p.getInventory().setItem(slot++,new ItemStack(item,n));left-=n;}}}
 private static void open(ServerPlayer p,net.minecraft.world.entity.Entity npc){var level=p.serverLevel();for(var pos:BlockPos.betweenClosed(npc.blockPosition().offset(-2,0,-2),npc.blockPosition().offset(2,0,2))){if(!level.getBlockState(pos).isAir()||!level.getBlockState(pos.above()).isAir()||!level.getBlockState(pos.below()).isFaceSturdy(level,pos.below(),Direction.UP))continue;p.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);if(p.hasLineOfSight(npc)&&p.distanceToSqr(npc)<25){CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)npc);return;}}throw new IllegalStateException("No valid nearby resident interaction position");}
}
